begin;
\ir fixtures/clinical.sql
create function pg_temp.import_row(n integer,phone text default'')returns jsonb language sql immutable as $$select jsonb_build_object('source_id','P'||n,'kind','patient','patient_source_id',null,'display_name','Synthetic imported person '||n,'birth_date','2000-01-01','phone',phone,'email','','starts_at',null,'state',null)$$;
create function pg_temp.import_appointment(ref text)returns jsonb language sql immutable as $$select jsonb_build_object('source_id','A1','kind','appointment','patient_source_id',ref,'display_name',null,'birth_date',null,'phone','','email','','starts_at','2026-01-01T10:00:00+02:00','state','cancelled')$$;
create function pg_temp.ic(action text,n integer,ver integer,k integer,input jsonb default'{}')returns jsonb language sql as $$select public.doctor_import_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(n),ver,action,input,pg_temp.id(k))$$;
create function pg_temp.ip(n integer,page integer default 0)returns jsonb language sql as $$select public.doctor_import_preview(pg_temp.practice(),pg_temp.location(),pg_temp.id(n),page)$$;
select pg_temp.put('canonical_count',to_jsonb(public.doctor_patients(pg_temp.practice(),pg_temp.location(),0,20,'','active')->>'total'));
select pg_temp.put('payload',jsonb_build_object('mapping_version','patient-appointment-v1','synthetic',true,'source_ref','Synthetic source custody demonstration','rows',jsonb_build_array(pg_temp.import_row(1),pg_temp.import_row(2),pg_temp.import_appointment('P1'))));
select is(pg_temp.ic('create',9500,0,9501,pg_temp.v('payload'))->>'cursor','0','C01: persist source manifest before staging');
select is(pg_temp.ic('create',9500,0,9501,pg_temp.v('payload'))->>'version','1','same manifest retry does not duplicate batch');
select throws_ok($$select pg_temp.ic('create',9501,0,9510,pg_temp.v('payload')||'{"synthetic":false}')$$,'22023','DOCTOR_IMPORT_INVALID','real dataset flag is denied');
select is(pg_temp.ic('next',9500,1,9502,'{"limit":1}')->>'cursor','1','first bounded page persists once');
select is(pg_temp.ic('next',9500,1,9502,'{"limit":1}')->>'cursor','1','lost chunk response replay does not advance twice');
select throws_ok($$select pg_temp.ic('reconcile',9500,2,9503)$$,'40001','DOCTOR_IMPORT_INCOMPLETE','interrupted batch cannot be silently accepted');
select is(pg_temp.ip(9500)->>'total','1','new read resumes saved cursor and counts');
select is(pg_temp.ic('next',9500,2,9504,'{"limit":50}')->>'cursor','3','resume processes only remaining source rows');
select is(pg_temp.ic('reconcile',9500,3,9505)->>'state','validated','exact complete valid manifest reconciles');
select is(pg_temp.ip(9500)->>'valid','3','reconciled totals include every row');
select is(pg_temp.ip(9500)->>'real_import','false','validated preview never enables real import');
select is(to_jsonb(public.doctor_patients(pg_temp.practice(),pg_temp.location(),0,20,'','active')->>'total'),pg_temp.v('canonical_count'),'canonical patients unchanged after complete preview');
select throws_ok($$select pg_temp.ic('apply',9500,4,9506)$$,'22023','DOCTOR_IMPORT_INVALID','no canonical apply command exists');
select pg_temp.ic('create',9600,0,9601,pg_temp.v('payload')||jsonb_build_object('rows',jsonb_build_array(pg_temp.import_row(1,'+15550001234'),pg_temp.import_row(2,'+15550001234'),pg_temp.import_appointment('MISSING'))));
select pg_temp.ic('next',9600,1,9602,'{"limit":50}');
select is(pg_temp.ic('reconcile',9600,2,9603)->>'state','review_required','C02: contact equality and unmatched references require explicit review');
select is(pg_temp.ip(9600)->>'review','2','both ambiguous contact candidates remain separate');
select is(pg_temp.ip(9600)#>>'{rows,2,errors,0}','unmatched_reference','unmatched appointment reference is visible');
select pg_temp.ic('create',9700,0,9701,pg_temp.v('payload')||jsonb_build_object('rows',jsonb_build_array(pg_temp.import_row(1)||'{"birth_date":"2026-02-30"}',pg_temp.import_row(1)||'{"display_name":"Real-looking name"}')));
select pg_temp.ic('next',9700,1,9702,'{"limit":50}');
select is(pg_temp.ic('reconcile',9700,2,9703)->>'state','review_required','bad dates, non-synthetic shape and duplicate source IDs block acceptance');
select is(pg_temp.ip(9700)->>'invalid','2','invalid rows retained with explicit errors, never partially imported');
select is(pg_temp.ic('discard',9700,3,9704)->>'state','discarded','rollback retires preview without canonical writes');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.ip(9500)$$,'42501','DOCTOR_ACCESS_DENIED','cross-doctor source staging denied');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.ic('create',9800,0,9801,pg_temp.v('payload'))$$,'42501','DOCTOR_ACCESS_DENIED','read-only staff cannot stage records');
select throws_ok($$select * from public.synthetic_import_batches$$,'42501',null,'raw source manifests have no direct client grant');
reset role;
select is((select count(*)::integer from public.synthetic_import_rows where batch_id=pg_temp.id(9500)),3,'same source replay preserves exactly three persisted rows');
select ok((select source_sha256=encode(sha256(convert_to(source_rows::text,'UTF8')),'hex')from public.synthetic_import_batches where id=pg_temp.id(9500)),'immutable source digest reconciles actual persisted manifest');
select * from finish();rollback;
